class Solution:
    def largestSumAfterKNegations(self, A: List[int], K: int) -> int:
        # Transform the problem: we want to flip the sign of numbers to maximize the sum.
        # Strategy:
        # 1. Flip all negative numbers to positive.
        # 2. If we still have moves left (K > 0), find the smallest absolute value in the array
        #    and flip its sign. If we have an even number of remaining moves, flipping the same
        #    number twice cancels out, so the net effect is zero. If odd, we flip it once.

        # Sort the array to easily process negative numbers and find the smallest absolute value
        A.sort()

        for i in range(len(A)):
            if K > 0 and A[i] < 0:
                A[i] = -A[i]
                K -= 1
            else:
                break

        # If we still have K > 0, we must flip the smallest element in the array
        # Find the minimum absolute value index
        min_idx = 0
        for i in range(1, len(A)):
            if abs(A[i]) < abs(A[min_idx]):
                min_idx = i

        if K % 2 == 1:
            A[min_idx] = -A[min_idx]

        return sum(A)

